using Microsoft.AspNetCore.Components.Authorization;
using sv_36ea17496ade4d2bb53e04b9711c27e1;
using sv_36ea17496ade4d2bb53e04b9711c27e1.Client.Pages;
using sv_36ea17496ade4d2bb53e04b9711c27e1.Components;

var builder = WebApplication.CreateBuilder(args);

